window.CHAPTER_QUESTION_BANK['8:自然:化學反應'] = [
  {origin:'國中教育會考官方題本',sourceUrl:CAP_114_NATURAL_SRC,sourceAnswerUrl:CAP_114_NATURAL_ANS,sourceAnswer:'B',questionNumber:19,tags:['化學反應','二氧化碳','碳酸鹽','碳捕捉'],screening:'國中教育會考114年自然科第19題',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'科學家研發出一種將二氧化碳變成岩石一部分的技術。上述二氧化碳變成岩石一部分的過程，是利用下列二氧化碳(水溶液)的何種性質？',answers:['密度大於空氣','溶於水呈酸性','可與鈣離子反應產生難溶於水的碳酸鹽','可與鈉離子反應產生易溶於水的碳酸鹽'],correct:2,explanation:'CO₂溶於水後與Ca²⁺反應生成CaCO₃沉澱（碳酸鹽），固化為岩石。',tip:'碳捕捉：CO₂+Ca²⁺→CaCO₃↓（難溶沉澱）。',},
  {origin:'國中教育會考官方題本',sourceUrl:CAP_113_NATURAL,sourceAnswerUrl:CAP_113_NATURAL_ANS,sourceAnswer:'A',questionNumber:23,tags:['化學反應','氧化還原','金屬冶煉'],screening:'國中教育會考113年自然科第23題',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'利用氫氣將金屬氧化物(MO)還原為金屬(M)的反應中，下列敘述何者正確？',answers:['氫被氧化，金屬氧化物被還原','氫被還原，金屬氧化物被氧化','氫和金屬氧化物都被氧化','氫和金屬氧化物都被還原'],correct:0,explanation:'H₂+MO→M+H₂O：氫得到氧被氧化（還原劑），MO失去氧被還原。',tip:'得氧=氧化（當還原劑），失氧=還原（當氧化劑）。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'D',questionNumber:1,tags:['化學反應','反應速率','催化劑'],screening:'國昌國中110八理化二次段考；直接比較反應速率影響因素，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'關於反應速率的敘述，下列何者錯誤？',answers:['反應物顆粒愈細，反應愈快','溫度愈高，碰撞頻率愈大，反應加快','濃度愈大，反應速率愈慢','催化劑參加反應，但最後質量未減少'],correct:2,explanation:'濃度愈大→單位體積內反應物粒子數增多→碰撞次數增加→反應速率加快，而非減慢。',tip:'反應速率四因素：顆粒大小、溫度、濃度、催化劑。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'C',questionNumber:5,tags:['化學反應','化學平衡'],screening:'八里國中108八理化二次段考；直接辨識化學平衡的定義，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'所謂化學平衡是指以下何者？',answers:['反應物與生成物的濃度相等','正逆反應速率完全停止，不再變化','正逆反應速率相等','反應物與生成物質量相等'],correct:2,explanation:'化學平衡=正反應速率=逆反應速率≠0，是動態平衡。',tip:'平衡≠停止，而是正逆反應速率相等。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'B',questionNumber:10,tags:['化學反應','化學平衡','催化劑'],screening:'八里國中108八理化二次段考；以哈柏法可逆反應判讀平衡操作，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'氮氣與氫氣在高溫、高壓下製氨的化學反應為一可逆反應，其反應式為 N₂＋3H₂↔2NH₃（Fe催化、400℃、200～1000 atm），當反應達平衡後，下列哪一項方法無法改變原平衡狀態？',answers:['增加氮氣與氫氣的濃度','增加催化劑的量','增高溫度','降低溫度'],correct:1,explanation:'催化劑只改變反應速率，不影響平衡位置。改變濃度或溫度才能使平衡移動。',tip:'催化劑=加快達平衡，但不改變平衡位置。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'B',questionNumber:14,tags:['化學反應','水溶液','離子'],screening:'八里國中108八理化二次段考；直接辨識決定酸鹼性的離子，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'下列哪一個離子的多寡可以代表水溶液的酸鹼性？',answers:['NH₄⁺','H⁺','NO₃⁻','CO₃²⁻'],correct:1,explanation:'[H⁺]>10⁻⁷M為酸性，[H⁺]<10⁻⁷M為鹼性，[H⁺]=10⁻⁷M為中性。',tip:'酸鹼性由[H⁺]決定，pH=-log[H⁺]。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'D',questionNumber:7,tags:['化學反應','電解質','導電'],screening:'八里國中108八理化二次段考；以電解質定義辨識正確敘述，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'有關電解質的敘述，下列何者正確？',answers:['只要能導電的物質就是電解質','食鹽不能導電，所以食鹽為非電解質','氫氧化鈉水溶液能導電，是因為含有金屬鈉原子','硫酸溶於水會解離出離子，所以水溶液可以導電'],correct:3,explanation:'電解質=溶於水能解離出離子而導電的化合物。固態NaOH不導電，但溶於水後解離出Na⁺和OH⁻能導電。',tip:'電解質看「溶於水後」能否導電，非看固態。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'A',questionNumber:20,tags:['化學反應','電解質','導電'],screening:'八里國中108八理化二次段考；以導電性辨識電解質，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'一個物質溶解於水時，會導電，該物質一定是下列何者？',answers:['酸','鹼','鹽','電解質'],correct:3,explanation:'酸、鹼、鹽都是電解質，但能導電的物質統稱為電解質，不限於某類。',tip:'導電的水溶液一定含電解質。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'D',questionNumber:34,tags:['化學反應','酸鹼中和','離子反應'],screening:'國昌國中110八理化二次段考；辨識酸鹼中和真正參與的離子，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'氫氧化鈉與鹽酸作用過程中，真正參加反應的是：',answers:['Na⁺與H⁺','Na⁺與Cl⁻','OH⁻與H⁺','Cl⁻與OH⁻'],correct:2,explanation:'NaOH+HCl→NaCl+H₂O，真正反應的是OH⁻+H⁺→H₂O（中和反應本質）。',tip:'酸鹼中和=H⁺+OH⁻→H₂O。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'A',questionNumber:41,tags:['化學反應','化學平衡','顏色變化'],screening:'國昌國中110八理化二次段考；以鉻酸根與重鉻酸根平衡辨識正確敘述，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'在2CrO₄²⁻(黃色)＋2H⁺↔Cr₂O₇²⁻(橘紅色)＋H₂O的平衡反應中，何者敘述正確？',answers:['達平衡後，顏色不再變化','平衡後[CrO₄²⁻]＝[Cr₂O₇²⁻]','平衡後正反應速率小於逆反應速率','平衡後溶液中CrO₄²⁻與Cr₂O₇²⁻莫耳數比＝2：1'],correct:0,explanation:'平衡時正逆反應速率相等，各物質濃度不再改變，因此顏色穩定不再變化。',tip:'平衡的巨觀特徵=各物質濃度（顏色）不再改變。',},
];

