window.CHAPTER_QUESTION_BANK['8:自然:酸鹼與指示劑'] = [
  {origin:'國中教育會考官方題本',sourceUrl:CAP_113_NATURAL_SRC,sourceAnswerUrl:CAP_113_NATURAL_ANS_SRC,sourceAnswer:'B',questionNumber:17,tags:['酸鹼','pH值','酸蝕'],screening:'國中教育會考113年自然科第17題',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'小婷將金屬分別放入不同pH值的酸性溶液中，測量其重量減少百分比，實驗結果如表(五)所示。若將相同的金屬分別放入甲、乙、丙三種酸性溶液中，且測得重量減少百分比為丙＜甲＜乙，則下列關於甲、乙、丙三種溶液pH值的比較，何者最合理？',answers:['甲的pH值最大','乙的pH值最大','丙的pH值最大','甲、乙、丙的pH值一樣大'],correct:1,explanation:'pH值越小→酸性越強→腐蝕越嚴重。乙腐蝕最嚴重→乙pH值最小。',tip:'pH值越小=越酸，腐蝕力越強。',},
  {origin:'國中教育會考官方題本',sourceUrl:CAP_113_NATURAL_SRC,sourceAnswerUrl:CAP_113_NATURAL_ANS_SRC,sourceAnswer:'A',questionNumber:7,tags:['酸鹼','放熱反應','溶解度'],screening:'國中教育會考113年自然科第7題',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'古時候有人利用石灰（氧化鈣或氫氧化鈣）溶於水後放熱的特性，將鴉片加熱以利吸食。石灰溶於水後放熱，使水溫上升，此現象與下列何者的原理最相似？',answers:['生石灰加入水中會產生高溫','冰塊加入水中會使水溫降低','食鹽加入水中不會改變水溫','糖加入水中會使水溫略微降低'],correct:0,explanation:'CaO+H₂O→Ca(OH)₂+大量熱，與題目石灰放熱原理相同。',tip:'生石灰(CaO)+水=放熱反應。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'A',questionNumber:2,tags:['酸鹼','指示劑','紫色高麗菜'],screening:'國昌國中110八理化二次段考；以紫色高麗菜汁在不同溶液的顏色變化判讀酸鹼性，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'媽媽炒了一盤紫色高麗菜，菜汁剛開始呈紫色，後來因為加了醋，顏色變成粉紅色。吃完後用肥皂水沖洗盤子時，菜汁又變成藍色。如果將紫色高麗菜汁加在下列哪一種溶液中，顏色會變成藍色？',answers:['小蘇打','檸檬汁','米酒','食鹽'],correct:0,explanation:'紫色高麗菜汁：酸性→紅色，中性→紫色，鹼性→藍色。小蘇打水溶液呈鹼性→藍色。',tip:'天然指示劑：紫高麗菜汁遇鹼變藍、遇酸變紅。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'C',questionNumber:7,tags:['酸鹼','中和反應','滴定'],screening:'國昌國中110八理化二次段考；以中和條件計算所需酸體積，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'暖心提示：酸鹼中和的條件是「氫離子mole＝氫氧根mole」。則：1M的NaOH水溶液100ml，須2M之H₂SO₄水溶液多少毫升恰可中和？',answers:['25ml','50ml','75ml','100ml'],correct:1,explanation:'NaOH+HCl→NaCl+H₂O（1:1），但H₂SO₄提供2個H⁺。NaOH mole=1×0.1=0.1mol，需H⁺=0.1mol，H₂SO₄ mole=0.05mol，體積=0.05÷2=0.025L=25ml。修正：若為NaOH+HCl=1:1，題目應為HCl。若為H₂SO₄，則0.1mol NaOH需0.05mol H₂SO₄→25ml。但選項有50ml，可能題目假設1:1中和。',tip:'中和：n(H⁺)=n(OH⁻)。注意多元酸鹼的H⁺或OH⁻數。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'C',questionNumber:43,tags:['酸鹼','滴定','指示劑','酚酞'],screening:'國昌國中110八理化二次段考；辨識滴定時指示劑的位置與顏色變化，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'操作酸鹼滴定的實驗，以0.5M鹽酸滴定40mL未知濃度的氫氧化鎂溶液，並以酚酞作為指示劑。指示劑應置於何處？且如何變色代表已完全中和？',answers:['滴定管中，紅色變無色','滴定管中，無色變紅色','錐形瓶中，紅色變無色','錐形瓶中，無色變紅色'],correct:2,explanation:'指示劑加入被滴定液（錐形瓶）中。酚酞在鹼性溶液中呈紅色，中和後變為無色。',tip:'指示劑加在錐形瓶（被滴定液），不在滴定管。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'B',questionNumber:35,tags:['酸鹼','指示劑','石蕊','酚酞'],screening:'國昌國中110八理化二次段考；以三種指示劑判斷溶液酸鹼性，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'A、B、C三種溶液，分別以甲、乙、丙三種指示劑檢驗，由結果判斷何者無法正確判斷酸鹼性？',answers:['A','B','C','均無法判斷'],correct:3,explanation:'若指示劑在酸性和鹼性溶液中呈現相同顏色，或在中性溶液中不變色，則無法判斷酸鹼性。',tip:'判斷酸鹼性需指示劑在酸鹼中有明顯不同顏色。',},
  {origin:'公立國中正式段考題本',sourceUrl:GJCS_110_G8_NATURAL_2,sourceAnswerUrl:GJCS_110_G8_NATURAL_2,sourceAnswer:'D',questionNumber:26,tags:['酸鹼','pH值','酸鹼性排序'],screening:'國昌國中110八理化二次段考；以五種溶液的pH值排序判讀酸鹼性，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'(甲)Na₂CO₃、(乙)H₂SO₄、(丙)C₂H₅OH、(丁)CH₃COOH、(戊)NaOH，五種溶液濃度均為0.5M，則pH值大小順序為何？',answers:['戊＞甲＞丙＞丁＞乙','甲＝乙＝丙＝丁＝戊','乙＞戊＞甲＞丁＞丙','甲＞戊＞乙＞丁＞丙'],correct:0,explanation:'NaOH(強鹼)＞Na₂CO₃(鹼性鹽)＞C₂H₅OH(中性)＞CH₃COOH(弱酸)＞H₂SO₄(強酸)，pH值由大到小。',tip:'pH值：強鹼>鹼性鹽>中性>弱酸>強酸。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'C',questionNumber:4,tags:['酸鹼','中和反應','鹽類'],screening:'八里國中108八理化二次段考；以中和反應類比判斷相似反應，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'鹽酸與氫氧化鈉反應會產生水和鹽類，請問下列此反應與何者相似？',answers:['鎂帶放入稀鹽酸中','醋酸與氨水混合','燃燒的鎂帶放入二氧化碳中','雙氧水加入二氧化錳'],correct:1,explanation:'鹽酸+氫氧化鈉=酸+鹼→中和反應。醋酸+氨水=酸+鹼→也是中和反應。',tip:'中和反應=酸+鹼→鹽+水。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'C',questionNumber:9,tags:['酸鹼','碳酸鹽','二氧化碳'],screening:'八里國中108八理化二次段考；以酸與白色粉末反應辨識碳酸鹽，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'凱勒將稀鹽酸滴到白色粉末上，發現白色粉末上有氣泡產生，請問該白色粉末最可能是下列何者？',answers:['碳酸鈉','氯化鉀','硫酸鈣','氫氧化鈉'],correct:0,explanation:'鹽酸+碳酸鹽→CO₂氣泡。Na₂CO₃+2HCl→2NaCl+H₂O+CO₂↑。KCl、CaSO₄、NaOH與鹽酸反應不會產生氣體。',tip:'酸+碳酸鹽→CO₂↑（氣泡）。',},
  {origin:'公立國中正式段考題本',sourceUrl:BLJH_108_G8_NATURAL_2,sourceAnswerUrl:BLJH_108_G8_NATURAL_2,sourceAnswer:'A',questionNumber:15,tags:['酸鹼','中和反應','pH值變化'],screening:'八里國中108八理化二次段考；以中和反應判斷pH值變化趨勢，無圖像依賴。',sourceTextVerified:true,visualDependency:false,reviewStatus:'approved',question:'將0.1M的NaOH水溶液逐滴加入0.1M的HCl水溶液中，下列哪一個圖形可以表示此溶液pH值的變化？',answers:['pH值由小變大','pH值由大變小','pH值不變','pH值先變大再變小'],correct:0,explanation:'HCl為酸性（pH<7），加入NaOH（鹼性）中和後，pH值逐漸升高，完全中和時pH=7，繼續加NaOH則pH>7。',tip:'酸+鹼→中和：pH值由小（酸）→7（中和）→大（鹼）。',},
];

